#!/usr/bin/env python3
"""Check BTS defined register/flag behavior through actual legacy x86 opcodes."""
import hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1];out=R/'generated/sse/bts-reference';out.mkdir(exist_ok=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();source=R/'tests/bts_oracle.c';table=out/'immediates.inc';table.write_text(''.join('case '+str(i)+':RUN("btsl $'+str(i)+', %%eax");break;\n' for i in range(256)));exe=out/'reference';sdk=subprocess.check_output(['xcrun','--sdk','macosx','--show-sdk-path'],text=True).strip();cmd=['clang','-target','x86_64-apple-macos12','-isysroot',sdk,'-std=c11','-O2','-mno-red-zone','-Wall','-Wextra','-Werror','-I',str(out),str(source),'-o',str(exe)];subprocess.run(cmd,check=True);run=subprocess.run([str(exe)],capture_output=True,text=True,timeout=60);assert not run.returncode and run.stdout.startswith('PASS:') and not run.stderr,(run.returncode,run.stdout,run.stderr);(out/'run.log').write_text(run.stdout);assembly=subprocess.check_output(['otool','-tvV',str(exe)],text=True);(out/'disassembly.txt').write_text(assembly);assert assembly.count('\tbtsl\t')==258
report={'pass':True,'cases':196608,'source_sha256':{str(p.relative_to(R)):sha(p) for p in [source,pathlib.Path(__file__).resolve(),table]},'binary_sha256':sha(exe),'compile_command':cmd,'output':run.stdout.strip(),'scope':'Canonical actual legacy BTS REG32 distinct/alias and all IMM8 bit offsets under Rosetta. Modulo32 index, selected-bit old CF and preserved ZF/nonundefined flags agree with independent integer expectations. OF/SF/AF/PF are architecturally undefined and excluded from canonical equality; emitted implementation retains them. Not physical Intel, memory BTS or fullDLL/gameplay proof.'};(out/'result.json').write_text(json.dumps(report,indent=2)+'\n');print(run.stdout.strip())
